###  RestTemplate SSL Support
If you need custom SSL configuration on the [`RestTemplate`](https://docs.spring.io/spring-framework/docs/6.2.x/javadoc-api/org/springframework/web/client/RestTemplate.html), you can apply an [SSL bundle](https://docs.spring.io/spring-boot/reference/features/ssl.html#features.ssl.bundles) to the [`RestTemplateBuilder`](https://docs.spring.io/spring-boot/3.5.4/api/java/org/springframework/boot/web/client/RestTemplateBuilder.html) as shown in this example:
  * Java
  * Kotlin


```
import org.springframework.boot.docs.io.restclient.resttemplate.Details;
import org.springframework.boot.ssl.SslBundles;
import org.springframework.boot.web.client.RestTemplateBuilder;
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestTemplate;

@Service
public class MyService {

	private final RestTemplate restTemplate;

	public MyService(RestTemplateBuilder restTemplateBuilder, SslBundles sslBundles) {
		this.restTemplate = restTemplateBuilder.sslBundle(sslBundles.getBundle("mybundle")).build();
	}

	public Details someRestCall(String name) {
		return this.restTemplate.getForObject("/{name}/details", Details.class, name);
	}

}
Copied!

```

